/**
 * The multi-cancer early detection tests of the October 2026 census, one record per test, and the companies behind
 * them that the corpus did not hold. The method, the sourcing rules and the papers are in ./mced-census.ts; Galleri
 * (drugs.ts) and Cancerguard (tests.ts) are supplemented in their own files rather than written again here.
 *
 * A test's summary keeps three things apart: what peer-reviewed papers report (with the cohort), what the developer
 * states about itself (labelled as the developer's), and regulatory status (stated only from the regulator or the
 * developer's own announcement). Where a fact could not be reached, the record says so.
 */
import type { CompanyInput, DrugInput } from "@/lib/schema";

const asOf = "2026-10-29";
const DOI = (label: string, doi: string) => ({ label, url: `https://doi.org/${doi}` });
const ct = (nct: string) => ({ label: `ClinicalTrials.gov ${nct}`, url: `https://clinicaltrials.gov/study/${nct}` });

type Grade = "strong" | "moderate" | "insufficient" | "no-benefit" | "harm";
const test = (grade: Grade, x: Omit<DrugInput, "kind" | "asOf">): DrugInput =>
  ({ kind: "drug", asOf, ...x, tags: ["test", "mced", `evidence:${grade}`, ...(x.tags ?? [])], technologies: ["mced", "liquid-biopsy", ...(x.technologies ?? []).filter((t) => t !== "mced" && t !== "liquid-biopsy")] });
const co = (x: Omit<CompanyInput, "kind" | "asOf">): CompanyInput => ({ kind: "company", asOf, sections: ["early-detection", "diagnostics"], ...x });

/** The grade reason shared by every test without a randomised trial. */
export const NO_RCT = "Evidence grade insufficient for the claim that taking this test reduces late-stage diagnosis or cancer deaths: no randomised trial of it has reported either outcome, and its published performance comes from case-control or single-arm studies. The only randomised result for any multi-cancer test, NHS-Galleri, did not show fewer stage III or IV cancers.";
const RESULT = "What a result means: a positive result is a reason for further tests, not a diagnosis; a negative result does not rule cancer out and does not replace the screening tests that have been shown to work (bowel, breast, cervical and, where eligible, lung screening).";

